8	/// Type for comparing two import sources.
9	/// Import sources are first grouped and ordered by [ImportSourceKind].
10	///
11	/// [ImportSourceKind::Path] are ordered according to their proximity of the current module.
12	/// For instance, the following order holds: `/` < `../..` < `..` < `.`
13	///
14	/// Other kinds are ordered with a natural string order tailored for paths.
15	/// See [ImportSourceAsciiCollator] for more details.
16	///
17	/// ```
18	/// use biome_rule_options::organize_imports::import_source::ImportSource;
19	///
20	/// assert!(ImportSource::from("https://example.org") < ImportSource::from("bun:test"));
21	/// assert!(ImportSource::from("node:test") < ImportSource::from("@scope/package"));
22	/// assert!(ImportSource::from("@scope/package") < ImportSource::from("package"));
23	/// assert!(ImportSource::from("package") < ImportSource::from("@/alias"));
24	/// assert!(ImportSource::from("@/alias") < ImportSource::from("/path"));
25	/// assert!(ImportSource::from("../..") < ImportSource::from(".."));
26	/// assert!(ImportSource::from("..") < ImportSource::from("."));
27	/// assert!(ImportSource::from("./path9") < ImportSource::from("./path10"));
28	/// assert!(ImportSource::from("./path/a") < ImportSource::from("./path-a"));
29	/// ```
30	#[derive(Clone, Debug, Eq, Hash, PartialEq)]
31	pub struct ImportSource<T> {
32	    kind: ImportSourceKind,
33	    inner: T,
34	}
35	impl<T> ImportSource<T> {
36	    pub fn kind(&self) -> ImportSourceKind {
37	        self.kind
38	    }
39	    pub fn inner(&self) -> &T {
40	        &self.inner
41	    }
42	}
43	impl<T: AsRef<str>> From<T> for ImportSource<T> {
44	    fn from(inner: T) -> Self {
45	        Self {
46	            kind: ImportSourceKind::from_source(inner.as_ref()),
47	            inner,
48	        }
49	    }
50	}
51	impl<T: AsRef<str> + Eq> PartialOrd for ImportSource<T> {
52	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
53	        Some(self.cmp(other))
54	    }
55	}
56	impl<T: AsRef<str> + Eq> Ord for ImportSource<T> {
57	    fn cmp(&self, other: &Self) -> Ordering {
58	        self.kind.cmp(&other.kind()).then_with(|| {
59	            if self.kind == ImportSourceKind::Path {
60	                PathComponents::from(Path::new(self.inner.as_ref()))
61	                    .cmp(PathComponents::from(Path::new(other.inner.as_ref())))
62	                    // [PathComponents] normalizes paths.
63	                    // This leads to a partial order between edge cases such as `./..` and `..`.
64	                    // To obtain a total order, we apply a string order when the normalized paths are equal.
65	                    .then_with(|| {
66	                        ImportSourceAsciiCollator.cmp_str(self.inner.as_ref(), other.inner.as_ref())
67	                    })
68	            } else {
69	                ImportSourceAsciiCollator.cmp_str(self.inner.as_ref(), other.inner.as_ref())
70	            }
71	        })
72	    }
73	}
