76	pub enum ImportSourceKind {
77	    Unknown,
78	    // `https://example.org`
79	    Url,
80	    /// `node:test`, `npm:@scope/package`
81	    ProtocolPackage,
82	    /// `package`
83	    Package,
84	    /// Import sources that start with `@/`, `#`, `~`, `$`, or `%`
85	    /// Node.js subpath imports and TypeScript aliases.
86	    Alias,
87	    /// Import sources that start with `/`, `./`, or `../`
88	    Path,
89	}
90	impl ImportSourceKind {
91	    pub fn from_source(import_source: &str) -> Self {
92	        let mut iter = import_source.bytes();
93	        match iter.next() {
94	            Some(b'@') => {
95	                match iter.next() {
96	                    Some(b'/') | None => {
97	                        // TypeScript conventional path aliases
98	                        Self::Alias
99	                    }
100	                    Some(b'a'..=b'z' | b'0'..=b'9' | b'-') => Self::Package,
101	                    _ => Self::Unknown,
102	                }
103	            }
104	            // Node.js subpath imports
105	            Some(b'#' | b'~' | b'$' | b'%') => Self::Alias,
106	            Some(b'/') => Self::Path,
107	            Some(b'.') => match iter.next() {
108	                Some(b'.') => {
109	                    if matches!(iter.next(), None | Some(b'/')) {
110	                        Self::Path
111	                    } else {
112	                        Self::Unknown
113	                    }
114	                }
115	                None | Some(b'/') => Self::Path,
116	                Some(_) => Self::Unknown,
117	            },
118	            Some(b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_') => {
119	                loop {
120	                    match iter.next() {
121	                        Some(b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.') => {}
122	                        Some(b':') => {
123	                            // Protocol
124	                            return match iter.next() {
125	                                Some(b'/') => Self::Url,
126	                                Some(b'@' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_') => {
127	                                    Self::ProtocolPackage
128	                                }
129	                                _ => Self::Unknown,
130	                            };
131	                        }
132	                        None | Some(b'/') => {
133	                            return Self::Package;
134	                        }
135	                        Some(_) => {
136	                            return Self::Unknown;
137	                        }
138	                    }
139	                }
140	            }
141	            _ => Self::Unknown,
142	        }
143	    }
144	}
